package com.astrocare.controller; import com.astrocare.dto.*; import com.astrocare.service.TelemetryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/demo") @RequiredArgsConstructor public class DemoController {private final TelemetryService service; @PostMapping("/simulate") @PreAuthorize("hasRole('FLIGHT_SURGEON')") public TelemetryResponse simulate(@Valid @RequestBody SimulationRequest r){return service.simulate(r);}}
